const variants=[
  {key:'a',name:'Missão guiada'},
  {key:'b',name:'Oficina de código'},
  {key:'c',name:'Fluxo da loja'}
];
const source=`<span class="comment"># Some os itens e aplique o desconto</span>\n<span class="kw">def</span> <span class="fn">atender_cliente</span>():\n    total = <span class="num">0</span>\n    preco = <span class="fn">input</span>()\n\n    <span class="kw">while</span> preco != -<span class="num">1</span>:\n        total = total + preco\n        preco = <span class="fn">input</span>()\n\n<span class="active-line">    <span class="kw">if</span> total &gt; <span class="num">50</span>:</span>\n        total = total * <span class="num">0.9</span>\n\n    <span class="fn">print</span>(<span class="str">"Total calculado:"</span>, total)\n    <span class="fn">send</span>(total)\n\n<span class="fn">atender_cliente</span>()`;
const editor=()=>`<div class="editor"><div class="lines">${Array.from({length:16},(_,i)=>i+1).join('<br>')}</div><pre class="code" contenteditable="true" spellcheck="false">${source}</pre></div>`;
const tabs=()=>`<div class="tabs"><button class="tab active"><span class="status-dot"></span> Principal.py</button><button class="tab"><span class="status-dot run"></span> Estoque.py</button><button class="tab">＋</button></div>`;
function variantA(){return `<section class="ide variant-a">
  <header class="a-top"><div class="brand pixel">AUTO<em>MARKET</em> / LAB</div><button class="quiet">? Ajuda</button><button class="action danger" data-action="stop">■ Parar</button><button class="action" data-action="run">▶ Testar código</button></header>
  <aside class="a-sidebar"><p class="mission-kicker pixel">MISSÃO 03 · LÓGICA</p><h1 class="mission-title">Decisões e desconto</h1><span class="muted">Progresso do desafio</span><div class="progress"><i></i></div><div class="goal"><strong>Objetivo</strong><span>Se a compra passar de R$ 50, aplique 10% de desconto e envie o total.</span></div><ul class="checklist"><li class="done">Ler todos os preços</li><li class="done">Parar ao receber -1</li><li>Aplicar a condição</li><li>Enviar o resultado</li></ul><button class="hint" data-action="hint">✦ Quero uma pista</button></aside>
  <section class="a-main">${tabs()}${editor()}<div class="a-output"><div class="panel-head"><span class="pixel">RESULTADO DO TESTE</span><button class="quiet" data-action="clear">Limpar</button></div><p class="console-line">› Cliente enviou: 18, 24, 20</p><p class="console-line ok">✓ Total calculado: R$ 55,80</p><p class="console-line muted">Seu código respondeu em 12 ms.</p></div></section>
  <footer class="a-status"><span>● Salvo agora</span><span>Python-like</span><span>Linha 9, Col 5</span></footer></section>`}
function variantB(){return `<section class="ide variant-b">
  <nav class="b-rail"><div class="rail-logo">A</div><button class="rail-btn active" title="Scripts">▤</button><button class="rail-btn" title="Buscar">⌕</button><button class="rail-btn" title="Documentação">?</button><button class="rail-btn" title="Saída">⌁</button><button class="rail-btn bottom" title="Voltar ao jogo">←</button></nav>
  <header class="b-titlebar"><div class="crumbs">scripts / <b>Principal.py</b></div><div class="run-cluster"><button class="quiet">Rodar todos</button><button class="action danger" data-action="stop">■</button><button class="action" data-action="run">▶ Rodar</button></div></header>
  <aside class="b-explorer"><div class="section-label pixel">AUTOMAÇÕES</div><button class="file active"><span class="status-dot"></span>Principal.py <small>PARADO</small></button><button class="file"><span class="status-dot run"></span>Estoque.py <small>RODANDO</small></button><button class="file"><span class="status-dot error"></span>Delivery.py <small>ERRO</small></button><button class="file">＋ Novo script</button><div class="doc-list"><div class="section-label pixel">REFERÊNCIA</div><button class="file">⌁ Atendimento</button><button class="file">⌁ Lógica</button><button class="file">⌁ Loja</button></div></aside>
  <section class="b-workbench"><div class="b-editor-head"><button class="tab active">Principal.py <span class="dirty">●</span></button><button class="tab">Estoque.py</button></div>${editor()}<div class="minimap"></div><div class="b-output"><div class="terminal"><div class="panel-head"><span class="pixel">TERMINAL</span><span class="muted">Principal.py</span></div><p class="console-line">&gt; iniciando automação...</p><p class="console-line ok">Total calculado: 55.8</p></div><div class="runtime-card"><span class="pixel">EXECUÇÕES</span><div class="runtime-row"><span>Principal</span><b>12 ms</b></div><div class="runtime-row"><span>Estoque</span><b style="color:var(--good)">ativo</b></div><div class="runtime-row"><span>Delivery</span><b style="color:var(--bad)">linha 8</b></div></div></div></section>
  <footer class="b-status"><span>✓ Python-like</span><span>Ln 9, Col 5</span><span class="push">2 scripts ativos</span><span>AutoMarket 0.7</span></footer></section>`}
function variantC(){return `<section class="ide variant-c">
  <header class="c-header"><h1>AUTOMAÇÕES DA LOJA</h1><div class="market-health"><span class="status-dot run"></span>Loja operando · 2 automações</div><button class="quiet">Documentação</button><button class="action" data-action="run">▶ Iniciar fluxo</button></header>
  <div class="c-layout"><section class="flow-board"><div class="flow-title"><div><h2>Atendimento automático</h2><p>Os scripts formam um fluxo. Clique em um bloco para editar.</p></div><button class="quiet">＋ Adicionar etapa</button></div><div class="pipeline">
    <article class="node"><div class="node-head"><span class="status-dot run"></span><h3>OBSERVAR</h3></div><p>Espera um cliente chegar e lê os itens do carrinho.</p><div class="node-footer"><span>sensor_cliente.py</span><b>ativo</b></div></article><i class="connector"></i>
    <article class="node active"><div class="node-head"><span class="status-dot"></span><h3>CALCULAR</h3></div><p>Soma os preços e aplica a regra de desconto da loja.</p><div class="node-footer"><span>Principal.py</span><b>editando</b></div></article><i class="connector"></i>
    <article class="node"><div class="node-head"><span class="status-dot run"></span><h3>RESPONDER</h3></div><p>Envia o total ao cliente e registra a venda.</p><div class="node-footer"><span>caixa.py</span><b>ativo</b></div></article></div>
    <div class="metrics"><div class="metric"><span class="muted">Atendimentos hoje</span><strong>24</strong></div><div class="metric"><span class="muted">Tempo médio</span><strong>18 ms</strong></div><div class="metric"><span class="muted">Falhas</span><strong>0</strong></div></div></section>
    <aside class="c-inspector"><div class="inspector-head"><span class="muted">ETAPA 2 DE 3</span><h2>CALCULAR · PRINCIPAL.PY</h2></div><div class="compact-editor">${editor()}</div><div class="c-log"><span class="pixel">ATIVIDADE</span><div class="event"><time>10:42</time><span>Venda de R$ 55,80 concluída</span></div><div class="event"><time>10:41</time><span>Desconto aplicado corretamente</span></div><div class="event"><time>10:40</time><span>Fluxo iniciado</span></div></div></aside></div></section>`}
const renderers={a:variantA,b:variantB,c:variantC};
function currentKey(){const key=new URLSearchParams(location.search).get('variant')?.toLowerCase();return variants.some(v=>v.key===key)?key:'a'}
function render(){const key=currentKey(),item=variants.find(v=>v.key===key);document.querySelector('#app').innerHTML=renderers[key]();document.querySelector('#variantLabel').textContent=`${key.toUpperCase()} — ${item.name}`;document.title=`${item.name} · AutoMarket`;bindActions()}
function cycle(delta){const i=variants.findIndex(v=>v.key===currentKey());const next=variants[(i+delta+variants.length)%variants.length];const url=new URL(location);url.searchParams.set('variant',next.key);history.replaceState({},'',url);render()}
function toast(text){const el=document.createElement('div');el.className='toast';el.textContent=text;document.body.append(el);setTimeout(()=>el.remove(),2300)}
function bindActions(){document.querySelectorAll('[data-action]').forEach(button=>button.addEventListener('click',()=>{const actions={run:'Teste concluído — resposta aceita!',stop:'Execuções interrompidas.',clear:'Saída limpa.',hint:'Pista: some tudo antes de testar total > 50.'};toast(actions[button.dataset.action])}))}
document.querySelector('#previousVariant').onclick=()=>cycle(-1);document.querySelector('#nextVariant').onclick=()=>cycle(1);addEventListener('popstate',render);addEventListener('keydown',event=>{if(['INPUT','TEXTAREA'].includes(document.activeElement.tagName)||document.activeElement.isContentEditable)return;if(event.key==='ArrowLeft')cycle(-1);if(event.key==='ArrowRight')cycle(1)});render();
